  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 1.5rem;
}

/* Skip link */
.skip-link {
  position: absolute;
  top: -100%;
  left: 1rem;
  background: var(--color-primary);
  color: #fff;
  padding: 0.5rem 1rem;
  border-radius: var(--radius-btn);
  font-size: 0.875rem;
  font-weight: 600;
  text-decoration: none;
  z-index: 100;
  transition: top var(--transition);
}
.skip-link:focus {
  top: 1rem;
  outline: 3px solid var(--color-primary-active);
  outline-offset: 2px;
}

