.card {
  background: var(--color-surface);
  border-radius: var(--radius-card);
  box-shadow: var(--shadow-card);
  padding: 2.5rem 2rem;
  width: 100%;
  max-width: 440px;
}

.card__header {
  margin-bottom: 2rem;
}

.card__logo {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  font-size: 1.125rem;
  font-weight: 700;
  color: var(--color-primary);
  margin-bottom: 1.25rem;
  text-decoration: none;
}

.card__logo svg {
  flex-shrink: 0;
}

.card__title {
  font-size: 1.5rem;
  font-weight: 700;
  line-height: 1.25;
  color: var(--color-text);
  margin-bottom: 0.375rem;
}

.card__subtitle {
  font-size: 0.9375rem;
  color: var(--color-muted);
  line-height: 1.5;
}

/* Form */
.form-field {
  margin-bottom: 1.5rem;
}

/* Checkbox row */
.checkbox-label {
  display: grid;
  grid-template-columns: 1.25rem 1fr;
  gap: 0.75rem;
  align-items: start;
  cursor: pointer;
  line-height: 1.5;
