.checkbox-text {
  font-size: 0.9375rem;
  color: var(--color-text);
  user-select: none;
}

.checkbox-text a {
  color: var(--color-primary);
  font-weight: 500;
  text-decoration: underline;
  text-underline-offset: 2px;
}

.checkbox-text a:hover {
  color: var(--color-primary-hover);
}

.checkbox-text a:focus-visible {
  outline: 3px solid transparent;
  box-shadow: var(--focus-ring);
  border-radius: 2px;
}

/* Helper / error text */
.field-hint {
  font-size: 0.8125rem;
  color: var(--color-muted);
  margin-top: 0.5rem;
  padding-left: calc(1.25rem + 0.75rem); /* align with label text */
}

.field-error {
  font-size: 0.8125rem;
  color: var(--color-error);
  margin-top: 0.5rem;
  padding-left: calc(1.25rem + 0.75rem);
  display: none;
}

.field-error[aria-hidden="false"],
.field-error:not([aria-hidden]) {
  display: block;
}

/* Submit button */
.btn-submit {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  width: 100%;
  padding: 0.75rem 1.5rem;
  background: var(--color-primary);
  color: #fff;
  font-size: 1rem;
  font-weight: 600;
  border: none;
  border-radius: var(--radius-btn);
  cursor: pointer;
  transition: background var(--transition), transform var(--transition), box-shadow var(--transition);
}

.btn-submit:hover {
  background: var(--color-primary-hover);
}

.btn-submit:active {
  background: var(--color-primary-active);
  transform: translateY(1px);
}

.btn-submit:focus-visible {
  outline: 3px solid transparent;
  box-shadow: var(--focus-ring);
}

/* Success state */
.success-message {
  display: none;
  align-items: center;
  gap: 0.75rem;
  background: var(--color-success-bg);
  border: 1.5px solid #bbf7d0;
  border-radius: var(--radius-btn);
  padding: 0.875rem 1rem;
  font-size: 0.9375rem;
  color: var(--color-success);
  font-weight: 500;
  margin-top: 1rem;
}

.success-message[aria-hidden="false"] {
  display: flex;
}

