+(function () {
+  "use strict";
+
+  const form = document.getElementById("consent-form");
+  const checkbox = document.getElementById("consent");
+  const errorEl = document.getElementById("consent-error");
+  const statusEl = document.getElementById("form-status");
+  const successEl = document.getElementById("success-message");
+
+  function showError(msg) {
+    errorEl.textContent = msg;
+    errorEl.setAttribute("aria-hidden", "false");
+    checkbox.setAttribute("aria-invalid", "true");
+    checkbox.setAttribute("aria-describedby", "consent-hint consent-error");
+  }
+
+  function clearError() {
+    errorEl.setAttribute("aria-hidden", "true");
+    checkbox.removeAttribute("aria-invalid");
+    checkbox.setAttribute("aria-describedby", "consent-hint");
+  }
+
+  /* Clear validation feedback as soon as the user checks the box */
+  checkbox.addEventListener("change", function () {
+    if (this.checked) clearError();
+  });
+
+  form.addEventListener("submit", function (e) {
+    e.preventDefault();
+
+    if (!checkbox.checked) {
+      showError("You must agree to the Terms of Use before continuing.");
+      checkbox.focus();
+      return;
+    }
+
+    clearError();
+
+    /* Show success */
+    successEl.setAttribute("aria-hidden", "false");
+    statusEl.textContent = "Form submitted successfully.";
+
+    /* Disable form after success */
+    checkbox.disabled = true;
+    form.querySelector(".btn-submit").disabled = true;
+    form.querySelector(".btn-submit").setAttribute("aria-disabled", "true");
+  });
